Given an n × n matrix mat[][] where each row and column is sorted in non-decreasing order, find the kth smallest element, where k lies in the range [1, n²].Example:Input:  mat[][] = [[10, 20, 30, 40],    k = 3                             [15, 25, 35, 45],                             [24, 29, 37, 48],                             [32, 33, 39, 50]]Output: 20Explanation: The sorted order is [10, 15, 20, ...]; the 3rd element is 20.Input:  mat[][] = [[10, 20, 30, 40],   k = 7                              [15, 25, 35, 45],                              [24, 29, 37, 48],                              [32, 33, 39, 50]]Output: 30Explanation: The sorted order is [10, 15, 20, 24, 25, 29, 30, ...]; the 7th element is 30.Try It YourselfTable of Content[Naive Approach] Using Sorting - O(n^2 × log n^2) Time and O(n) Space[Better Approach]  Using Priority Queue - O(n^2 × log(k)) Time and O(k) Space[Efficient Approach]  Binary Search on Answer[Naive Approach] Using Sorting - O(n2 × log n2) Time and O(n) SpaceInitialize a 1-dimensional array  of size n*n to store all the elements of the mat[][] , we will get our kth minimum element by sorting the 1-dimensional array in non-decreasing order.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int kthSmallest(vector<vector<int>>& mat, int k) {
    int n = mat.size();

    // create a vector to store all elements
    vector<int> arr;

    // store all elements of the mat 
    // into the array
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            arr.push_back(mat[i][j]);
        }
    }

    // sort the array
    sort(arr.begin(), arr.end());

    // return the kth smallest element 
    // (0-based index, hence k-1)
    return arr[k - 1];
}

int main() {
    vector<vector<int>> mat = 
                        {{10, 20, 30, 40},
                        {15, 25, 35, 45},
                        {24, 29, 37, 48},
                        {32, 33, 39, 50 }};
    int k = 3;
    int result = kthSmallest(mat, k);
    cout << result << endl;
    return 0;
}


