class GfG {
    static int kthSmallest(int[,] mat, int k) {
        int n = mat.GetLength(0);
        PriorityQueue<int> pq = 
        new PriorityQueue<int>
        (Comparer<int>.Create((a, b) => b.CompareTo(a)));

        // traverse all elements in the mat
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
