                // push the current element into the max-heap
                pq.Enqueue(curr);

                // if the size of the max-heap exceeds k, 
                // remove the largest element
                if (pq.Count > k) {
                    pq.Dequeue();
                }
            }
        }

        // the top element of the max-heap 
        // is the kth smallest element
        return pq.Peek();
    }

